import '../libraries/SafeMath.sol';
import '../libraries/Ownable.sol';
import '../libraries/TransferHelper.sol';
import '../interfaces/IERC20.sol';


contract BondTreasury is Ownable {
    /* ======== DEPENDENCIES ======== */
    using SafeMath for uint;

    /* ======== STATE VARIABLS ======== */

    address public immutable payoutToken;

    mapping(address => bool) public bondContract;

    /* ======== EVENTS ======== */

    event BondContractWhitelisted(address bondContract);
    event BondContractDewhitelisted(address bondContract);
    event Withdraw(address token, address destination, uint amount);

    /* ======== CONSTRUCTOR ======== */

    constructor(address _payoutToken) {
        require( _payoutToken != address(0) );
        payoutToken = _payoutToken;
    }

    /* ======== BOND CONTRACT FUNCTION ======== */

    /**
     *  @notice bond contract recieves payout tokens
     *  @param _amountPayoutToken uint
     */
    function sendPayoutTokens(uint _amountPayoutToken) external {
        require(bondContract[msg.sender], "msg.sender is not a bond contract");
        TransferHelper.safeTransfer(payoutToken, msg.sender, _amountPayoutToken);
    }

    /* ======== VIEW FUNCTION ======== */

    /**
    *   @notice returns payout token valuation of priciple
    *   @param _principalTokenAddress address
    *   @param _amount uint
    *   @return value_ uint
     */
    function valueOfToken( address _principalTokenAddress, uint _amount ) public view returns ( uint value_ ) {
        // convert amount to match payout token decimals
        value_ = _amount.mul( 10 ** IERC20( payoutToken ).decimals() ).div( 10 ** IERC20( _principalTokenAddress ).decimals() );
    }


    /* ======== OWNER FUNCTIONS ======== */

    /**
     *  @notice owner can withdraw ERC20 token to desired address
     *  @param _token uint
     *  @param _destination address
     *  @param _amount uint
     */
    function withdraw(address _token, address _destination, uint _amount) external onlyOwner {
        TransferHelper.safeTransfer(_token, _destination, _amount);
        emit Withdraw(_token, _destination, _amount);
    }

    /**
        @notice whitelist bond contract
        @param _bondContract address
     */
    function whitelistBondContract(address _bondContract) external onlyOwner {
        bondContract[_bondContract] = true;
        emit BondContractWhitelisted(_bondContract);
    }

    /**
        @notice dewhitelist bond contract
        @param _bondContract address
     */
    function dewhitelistBondContract(address _bondContract) external onlyOwner {
        bondContract[_bondContract] = false;
        emit BondContractDewhitelisted(_bondContract);
    }

}
"},"contracts/bonds/MuteBond.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import '../libraries/SafeMath.sol';
import '../libraries/TransferHelper.sol';

contract MuteBond {
    using SafeMath for uint;

    /* ======== EVENTS ======== */

    event BondCreated(uint deposit, uint payout, address depositor, uint time);
    event BondPriceChanged(uint internalPrice, uint debtRatio);
    event MaxPriceChanged(uint _price);
    event MaxPayoutChanged(uint _price);
    event EpochDurationChanged(uint _payout);
    event BondLockTimeChanged(uint _duration);
    event StartPriceChanged(uint _lock);

     /* ======== STATE VARIABLES ======== */

    address immutable private muteToken; // token paid for principal
    address immutable private dMuteToken;
    address immutable private lpToken; // inflow token
    ITreasury immutable private customTreasury; // pays for and receives principal
    uint public bond_time_lock = 7 days; // length of lockup in dMute for bonds

    uint public totalPayoutGiven; // total amount of mute paid
    uint public totalDebt; // total amount of LP collected

    uint public epochDuration = 7 days; // the length of an epoch from getting from startPrice  to maxPrice
    uint public maxPrice; // max limit price for the LP token (LP:mute ratio)
    uint public startPrice; // start price of the LP token (LP:mute ratio)
    uint public maxPayout; // max amount of mute tokens to sell in each epoch
    uint public epochStart; // timestamp of the current epoch start
    uint public epoch; // amount of cycles for bonds so far

    BondTerms[] public terms; // identifies the terms for a bond in a given epoch
    Bonds[] public bonds; // stores individual deposits

    // Info for bond epochs
    struct BondTerms {
        uint bondTotal; // amount of tokens bonded so far
        uint payoutTotal;
        uint lastTimestamp;
    }

    // Info for a single depositors bond info
    struct Bonds {
        uint value; //
        uint payout; //
        address depositor; //
        uint timestamp;
    }



    /* ======== CONSTRUCTOR ======== */

    /**
     *  @notice initializes the bond
     *  @param _customTreasury address
     *  @param _lpToken address
     *  @param _dmuteToken address
     *  @param _maxPrice uint
     *  @param _startPrice uint
     *  @param _maxPayout uint
     */
    constructor(address _customTreasury, address _lpToken, address _dmuteToken,
                uint _maxPrice, uint _startPrice, uint _maxPayout) {
        require( _customTreasury != address(0) && _lpToken != address(0));
        customTreasury = ITreasury( _customTreasury );
        muteToken = ITreasury(_customTreasury).payoutToken();
        dMuteToken = _dmuteToken;

        lpToken = _lpToken;

        // approve lock token to spend payout
        TransferHelper.safeApprove(muteToken, dMuteToken, type(uint256).max);


        require(_maxPrice >= _startPrice, "starting price < min");

        epochStart = block.timestamp;
        maxPrice = _maxPrice;
        startPrice = _startPrice;
        maxPayout = _maxPayout;

        terms.push(BondTerms(0,0,0));
    }


    /* ======== OWNER FUNCTIONS ======== */

    /**
     *  @notice sets the max limit price for the LP token
     *  @param _price uint
     */
    function setMaxPrice(uint _price) external {
        require(msg.sender == customTreasury.owner());
        maxPrice = _price;
        emit MaxPriceChanged(_price);
    }

    /**
     *  @notice sets the start price for the LP token
     *  @param _price uint
     */
    function setStartPrice(uint _price) external {
        require(msg.sender == customTreasury.owner());
        startPrice = _price;
        emit StartPriceChanged(_price);
    }

    /**
     *  @notice sets the max amount of mute tokens to sell in each epoch
     *  @param _payout uint
     */
    function setMaxPayout(uint _payout) external {
        require(msg.sender == customTreasury.owner());
        maxPayout = _payout;
        emit MaxPayoutChanged(_payout);
    }

    /**
     *  @notice sets the length of bond epoch
     *  @param _duration uint
     */
    function setEpochDuration(uint _duration) external {
        require(msg.sender == customTreasury.owner());
        epochDuration = _duration;
        emit EpochDurationChanged(_duration);
    }

    /**
     *  @notice sets the length of lockup for mute purchases in dMute
     *  @param _lock uint
     */
    function setBondTimeLock(uint _lock) external {
        require(msg.sender == customTreasury.owner());
        bond_time_lock = _lock;
        emit BondLockTimeChanged(_lock);
    }

    /* ======== USER FUNCTIONS ======== */

    /**
     *  @notice purchase a bond with LP, bump bond price back by 5% after purchase based on current delta
     *  @param value uint
     *  @param _depositor address
     *  @param max_buy bool
     */
    function deposit(uint value, address _depositor, bool max_buy) external returns (uint) {
        // amount of mute tokens
        uint payout = payoutFor( value );
        if(max_buy == true){
          value = maxPurchaseAmount();
          payout = maxDeposit();
        } else {
          // safety checks for custom purchase
          require( payout >= ((10**18) / 100), "Bond too small" ); // must be > 0.01 payout token ( underflow protection )
          require( payout <= maxPayout, "Bond too large"); // size protection because there is no slippage
          require( payout <= maxDeposit(), "Deposit too large"); // size protection because there is no slippage
        }


        // total debt is increased
        totalDebt = totalDebt.add( value );
        totalPayoutGiven = totalPayoutGiven.add(payout); // total payout increased

        customTreasury.sendPayoutTokens(payout);
        TransferHelper.safeTransferFrom(lpToken, msg.sender, address(customTreasury), value ); // transfer principal bonded to custom treasury

        // indexed events are emitted
        emit BondCreated(value, payout, _depositor, block.timestamp);

        bonds.push(Bonds(value, payout, _depositor, block.timestamp));
        // redeem bond for user, mint dMute tokens for duration of vest period
        IDMute(dMuteToken).LockTo(payout, bond_time_lock, _depositor);

        terms[epoch].payoutTotal = terms[epoch].payoutTotal + payout;
        terms[epoch].bondTotal = terms[epoch].bondTotal + value;
        terms[epoch].lastTimestamp = block.timestamp;

        // adjust price by a ~5% premium of delta
        uint timeElapsed = block.timestamp - epochStart;
        epochStart = epochStart.add(timeElapsed.mul(5).div(100));
        // safety check
        if(epochStart >= block.timestamp)
          epochStart = block.timestamp;

        // exhausted this bond, issue new one
        if(terms[epoch].payoutTotal == maxPayout){
            terms.push(BondTerms(0,0,0));
            epochStart = block.timestamp;
            epoch++;
        }

        return payout;
    }

    /* ======== HELPER FUNCTIONS ======== */


    /**
     *  @notice returns bond info for the current epoch and global values
     */
    function bondInfo() external view returns (uint totDebt, uint totPayout, uint price, uint maxDep, uint maxPurchase, uint maxPay) {
        totDebt = totalDebt;
        totPayout = totalPayoutGiven;
        price = bondPrice();
        maxDep = maxDeposit();
        maxPurchase = maxPurchaseAmount();
        maxPay = maxPayout;
    }

    /**
     *  @notice returns current epoch
     */
    function currentEpoch() public view returns (uint) {
        return epoch;
    }

    /**
     *  @notice returns current bond price
     */
    function bondPrice() public view returns (uint) {
        uint timeElapsed = block.timestamp - epochStart;
        uint priceDelta = maxPrice - startPrice;

        if(timeElapsed > epochDuration)
          timeElapsed = epochDuration;

        return timeElapsed.mul(priceDelta).div(epochDuration).add(startPrice);
    }

    /**
     *  @notice returns bond price for amount
     *  @param _am uint
     */
    function payoutFor(uint _am) public view returns (uint) {
        return bondPrice().mul(_am).div(10**18);
    }

    /**
     *  @notice returns max amount of lp tokens receivable in current bond epoch
     */
    function maxPurchaseAmount() public view returns (uint) {
        return maxDeposit().mul(10**18).div(bondPrice());
    }

    /**
     *  @notice returns remaining mute tokens in current bond epoch
     */
    function maxDeposit() public view returns (uint) {
        return maxPayout.sub(terms[epoch].payoutTotal);
    }

}

interface ITreasury {
    function sendPayoutTokens(uint _amountPayoutToken) external;
    function valueOfToken( address _principalTokenAddress, uint _amount ) external view returns ( uint value_ );
    function payoutToken() external view returns (address);
    function owner() external view returns (address);
}

interface IDMute {
  function LockTo(uint256 _amount, uint256 _lock_time, address to) external;
}
"},"contracts/dao/dMute.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import '../interfaces/IERC20.sol';
import '../libraries/SafeMath.sol';
import './dSoulBound.sol';

/// @notice Mute DAO token, untransferrable
contract dMute is dSoulBound {
    using SafeMath for uint;

    address public MuteToken;

    struct UserLockInfo {
      uint256 amount;
      uint256 time;
      uint256 tokens_minted;
    }

    mapping(address => UserLockInfo[]) public _userLocks;

    uint private unlocked = 1;

    event LockEvent(address to, uint256 lockAmount, uint256 mintedAmount, uint256 totalTime);
    event RedeemEvent(address to, uint256 unlockedAmount, uint256 burnAmount);

    modifier nonReentrant() {
        require(unlocked == 1, 'dMute::ReentrancyGuard: REENTRANT_CALL');
        unlocked = 0;
        _;
        unlocked = 1;
    }

    /// @dev Expects a LP token address & the base reward muteToken address
    constructor (address _muteToken) {
        require(_muteToken != address(0), "MuteAmplifier: invalid muteToken");
        MuteToken = _muteToken;
    }

    /*
    function lockBonus(uint256 lock_time) internal view returns (uint256){
        uint256 week_time = 60 * 60 * 24 * 7;
        uint256 max_lock = week_time.mul(52 * 2); // 2 years

        return lock_time.mul(10**18).div(max_lock).mul(10);
    }
    */

    function timeToTokens(uint256 _amount, uint256 _lock_time) internal pure returns (uint256){
        uint256 week_time = 1 weeks;
        uint256 max_lock = 52 weeks;

        require(_lock_time >= week_time, "dMute::Lock: INSUFFICIENT_TIME_PARAM");
        require(_lock_time <= max_lock, "dMute::Lock: INSUFFICIENT_TIME_PARAM");

        // amount * % of time locked up from min to max
        uint256 base_tokens = _amount.mul(_lock_time.mul(10**18).div(max_lock)).div(10**18);
        // apply % min max bonus
        //uint256 boosted_tokens = base_tokens.mul(lockBonus(lock_time)).div(10**18);

        return base_tokens;
    }

    function Lock(uint256 _amount, uint256 _lock_time) public {
        LockTo(_amount, _lock_time, msg.sender);
    }

    function LockTo(uint256 _amount, uint256 _lock_time, address to) public nonReentrant {
        require(IERC20(MuteToken).balanceOf(msg.sender) >= _amount, "dMute::Lock: INSUFFICIENT_BALANCE");

        //transfer tokens to this contract
        IERC20(MuteToken).transferFrom(msg.sender, address(this), _amount);

        // calculate dTokens to mint
        uint256 tokens_to_mint = timeToTokens(_amount, _lock_time);

        require(tokens_to_mint > 0, 'dMute::Lock: INSUFFICIENT_TOKENS_MINTED');

        _mint(to, tokens_to_mint);

        _userLocks[to].push(UserLockInfo(_amount, block.timestamp.add(_lock_time), tokens_to_mint));

        emit LockEvent(to, _amount, tokens_to_mint, _lock_time);
    }

    function Redeem(uint256[] memory lock_index) public {
        RedeemTo(lock_index, msg.sender);
    }

    function RedeemTo(uint256[] memory lock_index, address to) public nonReentrant {
        uint256 total_to_redeem = 0;
        uint256 total_to_burn = 0;

        for(uint256 i; i < lock_index.length; i++){
          uint256 index = lock_index[i];
          UserLockInfo memory lock_info = _userLocks[msg.sender][index];

          require(block.timestamp >= lock_info.time, "dMute::Redeem: INSUFFICIENT_LOCK_TIME");
          require(lock_info.amount >= 0 , "dMute::Redeem: INSUFFICIENT_AMOUNT");
          require(lock_info.tokens_minted >= 0 , "dMute::Redeem: INSUFFICIENT_MINT_AMOUNT");

          total_to_redeem = total_to_redeem.add(lock_info.amount);
          total_to_burn = total_to_burn.add(lock_info.tokens_minted);

          _userLocks[msg.sender][index] = UserLockInfo(0,0,0);
        }

        require(total_to_redeem > 0, "dMute::Lock: INSUFFICIENT_REDEEM_AMOUNT");
        require(total_to_burn > 0, "dMute::Lock: INSUFFICIENT_BURN_AMOUNT");


        for(uint256 i = _userLocks[msg.sender].length; i > 0; i--){
          UserLockInfo memory lock_info = _userLocks[msg.sender][i - 1];

          // recently redeemed lock, destroy it
          if(lock_info.time == 0){
            _userLocks[msg.sender][i - 1] = _userLocks[msg.sender][_userLocks[msg.sender].length - 1];
            _userLocks[msg.sender].pop();
          }
        }

        //redeem tokens to user
        IERC20(MuteToken).transfer(to, total_to_redeem);
        //burn dMute
        _burn(msg.sender, total_to_burn);


        emit RedeemEvent(msg.sender, total_to_redeem, total_to_burn);
    }

    function GetUserLockLength(address account) public view returns (uint256 amount) {
        amount = _userLocks[account].length;
    }

    function GetUnderlyingTokens(address account) public view returns(uint256 amount) {
        for(uint256 i; i < _userLocks[account].length; i++){
          amount = amount.add(_userLocks[account][i].amount);
        }
    }
}
